const item = $input.first();
const content = item.json.choices[0].message.content;
let email = {};
try { email = JSON.parse(content); } catch(e) { email = { subject: 'Quick question', body: content }; }
return [{ json: { ...item.json._lead, generated_subject: email.subject, generated_body: email.body } }];
